export type Hold = { from: string; to: string };

/** Whether the date (yyyy-MM-dd) is within one of the holds. */
export const heldOn = (holds: Hold[], date: string) =>
  holds.some((h) => h.from <= date && (h.to === '' || date <= h.to));

/**
 * The holds a person's claims count against on the sheet's `today`: their own, and from the day
 * their retirement date is reached (`today` on or after it) one covering every date — their OPEN
 * and PENDING claims, unless a statement binds them, then count in no total.
 */
export const liveHolds = (p: Pick<Person, 'holds' | 'retiredFrom'>, today: string): Hold[] =>
  p.retiredFrom !== '' && today !== '' && p.retiredFrom <= today ? [...p.holds, { from: '', to: '' }] : p.holds;

export const peopleKey = (sheetId: string) => ['sheet', sheetId, 'people'] as const;

export const peopleQuery = (sheetId: string) => ({
  queryKey: peopleKey(sheetId),
  queryFn: async () =>
    (await getJson<{ people: Person[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/people`)).people,
 * A claim number, as a correction names the claim it corrects: a sheet-wide number (one given
 * before numbering restarted each fiscal year), a number within a fiscal year (<FY>-<n>), or a number
 * within a period (<period name>-<n>, X-<n> for a claim in no period).
 */
export const CLAIM_NUMBER = /^(\d+|.+-\d+)$/;

/**
 * The amounts of the claims that count (OPEN, PENDING and SETTLED, but not unbound open ones dated within
 * a hold of their person: `holds` tells by person id, nor ones deferred on `today`), leaving out corrections, added up, in whole cents so no rounding creeps in, shown with two
 * decimals.
 */
export function sumAmounts(claims: Claim[], holds: (personId: string) => Hold[], today: string): string {
  const cents = claims.filter((c) => !isCorrection(c) && counts(c, holds(c.personId), today)).reduce((n, c) => n + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

